from collections import deque
R,C=len(g),len(g[0]); seen=set(); objs=[]
for r in range(R):
 for c in range(C):
  v=g[r][c]
  if v and (r,c) not in seen:
   q=[(r,c)];seen.add((r,c)); cells=[]
   while q:
    x,y=q.pop();cells.append((x,y))
    for z in [(x+1,y),(x-1,y),(x,y+1),(x,y-1)]:
     if 0<=z[0]<R and 0<=z[1]<C and z not in seen and g[z[0]][z[1]]==v:seen.add(z);q.append(z)
   objs.append((v,cells))
# sequential rightmost-first
occ=set((r,c) for v,cells in objs for r,c in cells)
placed=[]
for v,cells in sorted(objs,key=lambda o:max(c for r,c in o[1]),reverse=True):
 occ.difference_update(cells); d=0
 while all(c+d+1<C and (r,c+d+1) not in occ for r,c in cells):d+=1
 nc=[(r,c+d) for r,c in cells];occ.update(nc);placed.append((v,nc,d))
out=[[0]*C for _ in range(R)]
for v,cs,d in placed:
 for r,c in cs:out[r][c]=v
print(*out,sep='\n')
